insert into public.posts(client_id,tag_id,title,body,cover_text,image_url,is_demo,status) values
(1,(select id from public.interest_tags where name='生活'),'给周末留一小时空白','不必把休息排成另一份任务清单。试着关掉提醒，带一本书去街角，观察光如何慢慢移过桌面。','一小时的慢','https://images.unsplash.com/photo-1449247709967-d4461a6a6103?auto=format&fit=crop&w=900&q=82',true,'published'),
(2,(select id from public.interest_tags where name='摄影'),'雨后街道的五种颜色','湿润的地面会把平常被忽略的招牌、树影和天空叠在一起。试着蹲低一点，用倒影重新构图。','雨后的街道','https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=900&q=82',true,'published'),
(3,(select id from public.interest_tags where name='设计'),'一把椅子的留白','好设计不一定需要更多元素。材料的温度、坐下时的角度和可维修的结构，同样是设计语言。','有用的留白','https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?auto=format&fit=crop&w=900&q=82',true,'published'),
(4,(select id from public.interest_tags where name='科技'),'把通知改成主动查看','技术应该替你节省注意力。为不紧急的消息设定固定查看时间，能让工作与生活都更完整。','温和的技术','https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=82',true,'published'),
(5,(select id from public.interest_tags where name='游戏'),'为什么小地图让人安心','在陌生世界中，一个清晰的方向标会降低探索成本。但最难忘的惊喜往往藏在地图之外。','地图之外','https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=82',true,'published'),
(6,(select id from public.interest_tags where name='情感'),'认真听完一句话','回应之前停一秒，确认自己听见的是对方的意思，而不是自己准备好的答案。','倾听练习','https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&w=900&q=82',true,'published'),
(7,(select id from public.interest_tags where name='知识'),'一杯茶里的微小科学','热水让茶叶中的香气逐渐释放。水温、时间与容器形状，都会改变你感受到的层次。','日常里的科学','https://images.unsplash.com/photo-1544787219-7f47ccb76574?auto=format&fit=crop&w=900&q=82',true,'published'),
(8,(select id from public.interest_tags where name='艺术'),'在美术馆看一幅画十分钟','先不看说明。留意最先吸引你的线条，再慢慢寻找画面里的重复与意外。','慢看一幅画','https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&w=900&q=82',true,'published'),
(9,(select id from public.interest_tags where name='生活'),'一张真正能用的清单','清单只写今天最重要的三件事。完成后留下余地，让生活有机会发生。','轻一点的日程','https://images.unsplash.com/photo-1449247709967-d4461a6a6103?auto=format&fit=crop&w=900&q=82',true,'published'),
(10,(select id from public.interest_tags where name='摄影'),'清晨逆光的人物轮廓','逆光会隐藏细节，却把姿态留得更清楚。让背景简单，轮廓自然会说话。','清晨轮廓','https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=900&q=82',true,'published'),
(11,(select id from public.interest_tags where name='设计'),'包装拆开之后','设计的责任不在打开包装那一刻结束。减少难以分离的材料，让使用后的处理也顺畅。','包装的下一站','https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?auto=format&fit=crop&w=900&q=82',true,'published'),
(12,(select id from public.interest_tags where name='科技'),'给旧设备第二次机会','清理文件、替换电池、安装轻量软件，可能比购买新设备更能解决眼前问题。','设备的第二春','https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=82',true,'published'),
(13,(select id from public.interest_tags where name='游戏'),'合作游戏里的好沟通','清晰报点和一句及时鼓励，比复杂战术更能让陌生队友形成默契。','一起过关','https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=82',true,'published'),
(14,(select id from public.interest_tags where name='情感'),'允许关系有安静时刻','亲近不意味着时时刻刻都要交谈。共同沉默也可以是一种自在的陪伴。','舒服的沉默','https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&w=900&q=82',true,'published'),
(15,(select id from public.interest_tags where name='知识'),'怎样记住刚读过的内容','读完一小段后，用自己的话写下一句总结。能讲清楚，才更可能真正理解。','一句话笔记','https://images.unsplash.com/photo-1544787219-7f47ccb76574?auto=format&fit=crop&w=900&q=82',true,'published'),
(16,(select id from public.interest_tags where name='艺术'),'城市墙面上的手写字','转角处的旧招牌有独特节奏。记录这些字，也是在保存一座城市的记忆。','街头字迹','https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&w=900&q=82',true,'published'),
(17,(select id from public.interest_tags where name='生活'),'厨房里的低成本仪式感','认真摆好一只碗，给普通的晚餐留一点时间。仪式感并不依赖昂贵的物品。','好好吃饭','https://images.unsplash.com/photo-1449247709967-d4461a6a6103?auto=format&fit=crop&w=900&q=82',true,'published'),
(18,(select id from public.interest_tags where name='摄影'),'让阴影成为主角','正午的强光常被视为麻烦，却也创造了锐利的几何线条。换个角度，阴影就是主题。','光的另一面','https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=900&q=82',true,'published'),
(19,(select id from public.interest_tags where name='设计'),'更容易读的说明书','一句清楚的提示、恰好的字号和正确的步骤顺序，比华丽插图更值得被认真设计。','说明的设计','https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?auto=format&fit=crop&w=900&q=82',true,'published'),
(20,(select id from public.interest_tags where name='科技'),'个人数据的整理日','每月花十五分钟检查应用权限，删除不再使用的账号，给数字生活做一次轻量清扫。','数字整理日','https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=82',true,'published'),
(21,(select id from public.interest_tags where name='游戏'),'失败也有趣的关卡','好的关卡会让你知道为什么失败，并愿意马上再试一次。反馈清楚，是公平感的来源。','再试一次','https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=82',true,'published'),
(22,(select id from public.interest_tags where name='情感'),'给朋友一个具体的夸奖','与其说“你真棒”，不如说出哪一个瞬间让你感到被理解。具体的话更容易被记住。','具体的感谢','https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&w=900&q=82',true,'published'),
(23,(select id from public.interest_tags where name='知识'),'从一张地图开始了解城市','沿着河流、车站与老街观察城市，许多看似偶然的布局就有了可解释的原因。','读懂一座城','https://images.unsplash.com/photo-1544787219-7f47ccb76574?auto=format&fit=crop&w=900&q=82',true,'published'),
(24,(select id from public.interest_tags where name='艺术'),'听一首歌的低音线','熟悉的旋律之外，低音常在悄悄推动情绪。戴上耳机，试着只追随它走一遍。','听见底色','https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&w=900&q=82',true,'published'),
(25,(select id from public.interest_tags where name='生活'),'植物的生长记录','每周在同一个角度拍一张照片。慢慢积累的变化，能提醒我们耐心有自己的节奏。','慢慢生长','https://images.unsplash.com/photo-1449247709967-d4461a6a6103?auto=format&fit=crop&w=900&q=82',true,'published'),
(26,(select id from public.interest_tags where name='摄影'),'拍下家附近的同一个角落','季节、天气、路过的人都会改变画面。重复拍摄能让熟悉的地方再次变得新鲜。','同一个角落','https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=900&q=82',true,'published'),
(27,(select id from public.interest_tags where name='设计'),'耐用也可以很美','细节经得起反复使用，材料能够修补替换，这种美感往往比短暂的新奇更持久。','时间的设计','https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?auto=format&fit=crop&w=900&q=82',true,'published'),
(28,(select id from public.interest_tags where name='科技'),'搜索之前先问好问题','把模糊需求写成具体问题，注明背景与限制。更好的输入通常带来更有用的结果。','问题的形状','https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=82',true,'published'),
(29,(select id from public.interest_tags where name='游戏'),'游戏音乐如何提示风险','速度、音色和重复会悄悄改变你的判断。下一次游玩时，留意音乐如何引导你行动。','听见关卡','https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=82',true,'published'),
(30,(select id from public.interest_tags where name='艺术'),'手作留下的微小差异','每件手作物都有一点不规则。正是这些痕迹，让材料与制作者的时间被看见。','手的痕迹','https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&w=900&q=82',true,'published'),
(31,(select id from public.interest_tags where name='生活'),'冰箱里的一顿晚餐','先看现有食材，再决定菜单，减少临时采购。把切菜和收拾也算进时间，简单的一餐就不必匆忙。','食材与晚餐','https://images.unsplash.com/photo-1544787219-7f47ccb76574?auto=format&fit=crop&w=900&q=82',true,'published'),
(32,(select id from public.interest_tags where name='生活'),'给通勤留一段步行','提前一站下车，观察沿路店铺和树木的变化。固定路线里的微小差异，会让熟悉的城市重新展开。','沿路观察','https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&w=900&q=82',true,'published'),
(33,(select id from public.interest_tags where name='生活'),'周日整理一张桌面','只留下本周会用到的东西，其他物件各自归位。桌面清楚以后，开始一件小事也更容易。','清爽桌面','https://images.unsplash.com/photo-1449247709967-d4461a6a6103?auto=format&fit=crop&w=900&q=82',true,'published'),
(34,(select id from public.interest_tags where name='生活'),'把家务拆成十分钟','把洗杯子、擦台面和叠衣服分开安排。短任务有明确结束点，比等待一个完整空闲时段更实际。','十分钟家务','https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=900&q=82',true,'published'),
(35,(select id from public.interest_tags where name='生活'),'记录一件修好的东西','旧物修复不只是省钱，也能让人重新理解它的结构。记录过程，下次遇到相似问题就有了自己的说明书。','修复记录','https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?auto=format&fit=crop&w=900&q=82',true,'published'),
(36,(select id from public.interest_tags where name='生活'),'让早餐有固定位置','为钥匙、耳机和水杯安排一个顺手的位置。稳定的小秩序能减少早晨寻找物品的时间。','早晨秩序','https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=82',true,'published'),
(37,(select id from public.interest_tags where name='摄影'),'用窗边光拍一只杯子','侧光会强调杯沿和液体的透明度。移动杯子而不是提高曝光，能更细致地控制高光形状。','窗边静物','https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=82',true,'published'),
(38,(select id from public.interest_tags where name='摄影'),'长曝光记录夜间车流','固定相机并缩小光圈，让移动的车灯留下连续线条。先试短曝光，再根据车流速度调整时间。','夜间轨迹','https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&w=900&q=82',true,'published'),
(39,(select id from public.interest_tags where name='摄影'),'用广角拍狭窄巷子','靠近前景能强化纵深，但边缘物体会被拉伸。把重要主体放在画面中间附近，空间感会更自然。','巷道纵深','https://images.unsplash.com/photo-1544787219-7f47ccb76574?auto=format&fit=crop&w=900&q=82',true,'published'),
(40,(select id from public.interest_tags where name='摄影'),'给阴天留住灰阶','阴天的光线柔和，适合观察皮肤、石墙和衣料的细微色差。降低一点对比度，画面会保留更多层次。','阴天色阶','https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&w=900&q=82',true,'published'),
(41,(select id from public.interest_tags where name='摄影'),'拍摄玻璃后的倒影','让焦点落在玻璃上的反射，室内外景物会叠成一张画面。改变拍摄角度，可以控制两层影像的比例。','玻璃倒影','https://images.unsplash.com/photo-1449247709967-d4461a6a6103?auto=format&fit=crop&w=900&q=82',true,'published'),
(42,(select id from public.interest_tags where name='摄影'),'练习只拍一种颜色','选择街区里一种颜色，寻找招牌、衣物和交通设施的呼应。限制主题能训练筛选，而不是只增加快门次数。','颜色练习','https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=900&q=82',true,'published'),
(43,(select id from public.interest_tags where name='设计'),'图标为何需要光学修正','几何上相同的圆和方，看起来往往并不一样大。调整边缘越界量，是为了让视觉重量真正接近。','图标比例','https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?auto=format&fit=crop&w=900&q=82',true,'published'),
(44,(select id from public.interest_tags where name='设计'),'菜单上的阅读顺序','字号、间距和分组会暗示顾客先看什么。把高频选择放在容易扫到的位置，能减少来回寻找。','菜单层级','https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=82',true,'published'),
(45,(select id from public.interest_tags where name='设计'),'纸张触感也在传达信息','克重、纹理和反光会影响读者对内容的第一印象。触感应该帮助识别和阅读，而不是只增加装饰。','纸张触感','https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=82',true,'published'),
(46,(select id from public.interest_tags where name='设计'),'为表单减少一次输入','如果系统已经知道日期或地区，就不必再次询问。少一个字段，也能降低填错和中途放弃的机会。','表单减负','https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&w=900&q=82',true,'published'),
(47,(select id from public.interest_tags where name='设计'),'按钮状态需要被看见','按下、禁用和完成状态应有清晰差异。及时反馈让人知道操作已经生效，不必重复点击。','按钮反馈','https://images.unsplash.com/photo-1544787219-7f47ccb76574?auto=format&fit=crop&w=900&q=82',true,'published'),
(48,(select id from public.interest_tags where name='设计'),'把说明放到需要的地方','用户遇到选择困难时，旁边的一句话通常比远处的帮助中心更有用。说明应回答眼前问题，不要堆砌术语。','就近说明','https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&w=900&q=82',true,'published'),
(49,(select id from public.interest_tags where name='科技'),'离线优先的笔记习惯','先在本地保存，再于网络恢复时同步，可以减少断网时的工作中断。冲突记录也需要明确展示，而不是悄悄覆盖。','离线笔记','https://images.unsplash.com/photo-1449247709967-d4461a6a6103?auto=format&fit=crop&w=900&q=82',true,'published'),
(50,(select id from public.interest_tags where name='科技'),'密码管理器的主密码','主密码既要足够独特，也要能长期记住。用一段自己熟悉但不公开的句子，比在多个网站复用短密码稳妥。','主密码','https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=900&q=82',true,'published'),
(51,(select id from public.interest_tags where name='科技'),'浏览器标签页的边界','标签开太多会让注意力分散，也增加恢复成本。把需要稍后阅读的页面收进清单，当前窗口只保留手头工作。','标签整理','https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?auto=format&fit=crop&w=900&q=82',true,'published'),
(52,(select id from public.interest_tags where name='科技'),'地图定位为何会漂移','高楼反射、室内遮挡和低功耗模式都会影响定位精度。查看附近地标并稍等片刻，通常比立即重试更有效。','定位误差','https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=82',true,'published'),
(53,(select id from public.interest_tags where name='科技'),'为旧手机做一次安全检查','确认系统更新、屏幕锁和应用权限，再移除不用的软件。设备变慢时，先检查存储空间和后台进程。','手机检查','https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=82',true,'published'),
(54,(select id from public.interest_tags where name='科技'),'自动化不等于无人负责','脚本能减少重复操作，但输入异常仍需要监控和回滚方案。可靠的自动化会留下记录，也能安全地停止。','自动化边界','https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&w=900&q=82',true,'published'),
(55,(select id from public.interest_tags where name='游戏'),'新手引导如何不打断探索','好的引导在玩家需要时才出现，并允许跳过熟悉步骤。让规则在具体场景里被体验，比一次读完长说明更自然。','适时引导','https://images.unsplash.com/photo-1544787219-7f47ccb76574?auto=format&fit=crop&w=900&q=82',true,'published'),
(56,(select id from public.interest_tags where name='游戏'),'音效里的方向线索','左右声道和音量差能帮助玩家判断危险位置。戴耳机测试时，也要提供字幕或视觉提示照顾不同听觉条件。','声音方向','https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&w=900&q=82',true,'published'),
(57,(select id from public.interest_tags where name='游戏'),'关卡里的安全练习区','在真正的挑战前提供一次低风险尝试，玩家便能理解操作后果。练习应教会机制，而不是只重复按键。','练习关卡','https://images.unsplash.com/photo-1449247709967-d4461a6a6103?auto=format&fit=crop&w=900&q=82',true,'published'),
(58,(select id from public.interest_tags where name='游戏'),'道具稀缺如何塑造选择','有限资源会让每次使用都带有判断。若玩家无法理解补给频率，稀缺只会变成焦虑而非策略。','有限补给','https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=900&q=82',true,'published'),
(59,(select id from public.interest_tags where name='游戏'),'多人游戏的等待时间','组队等待时提供练习或进度提示，能让空档更有意义。匹配结束后应清楚提醒玩家回到队伍。','等待体验','https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?auto=format&fit=crop&w=900&q=82',true,'published'),
(60,(select id from public.interest_tags where name='游戏'),'开放世界中的小目标','远处的大任务之外，路边的收集物和短事件也能形成节奏。让这些小目标有变化，探索才不会像清单打卡。','路上的小事','https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=82',true,'published'),
(61,(select id from public.interest_tags where name='情感'),'争执时先确认共同事实','情绪升高时，双方可能记住不同的细节。先复述彼此认可的事实，再谈解释，能减少围绕误会的争论。','共同事实','https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=82',true,'published'),
(62,(select id from public.interest_tags where name='情感'),'给拒绝留出温和边界','清楚表达不能接受的安排，不必附上过多辩解。尊重自己的时间，也给对方机会重新协商。','温和拒绝','https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&w=900&q=82',true,'published'),
(63,(select id from public.interest_tags where name='情感'),'长距离联系的节奏','不必用即时回复衡量关系亲疏。约好一个双方舒服的联系频率，比持续追问是否在线更让人安心。','联系节奏','https://images.unsplash.com/photo-1544787219-7f47ccb76574?auto=format&fit=crop&w=900&q=82',true,'published'),
(64,(select id from public.interest_tags where name='情感'),'谢谢也可以说得具体','指出对方做了什么、给你带来什么帮助，感谢就更有温度。具体回忆也让善意不容易被忽略。','具体感谢','https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&w=900&q=82',true,'published'),
(65,(select id from public.interest_tags where name='情感'),'照顾情绪先照顾身体','疲惫、饥饿和缺觉会放大烦躁感。先喝水、吃饭或短暂休息，再决定如何回应问题。','身体与情绪','https://images.unsplash.com/photo-1449247709967-d4461a6a6103?auto=format&fit=crop&w=900&q=82',true,'published'),
(66,(select id from public.interest_tags where name='情感'),'把道歉落到下一步行动','承认造成的影响之后，说清楚准备怎样修正。持续做到的改变，比一次漂亮的解释更能重建信任。','道歉之后','https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=900&q=82',true,'published'),
(67,(select id from public.interest_tags where name='知识'),'一张纸如何吸收水分','纸纤维之间的小空隙会让液体沿着材料扩散。不同纸张的纤维密度和涂层，会改变吸水速度。','纸与水','https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?auto=format&fit=crop&w=900&q=82',true,'published'),
(68,(select id from public.interest_tags where name='知识'),'为什么山路常有弯道','弯道能减缓坡度，让车辆和行人更容易通过。地形、视线和排水条件也会共同影响道路路线。','山路曲线','https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=82',true,'published'),
(69,(select id from public.interest_tags where name='知识'),'冰块为何浮在水面','水结冰时形成较疏松的晶体结构，体积变大、密度降低。这个少见特性让湖面结冰时水下仍可保持液态。','浮起的冰','https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=82',true,'published'),
(70,(select id from public.interest_tags where name='知识'),'植物朝光生长的原因','茎会根据光线方向调整生长，帮助叶片获得更多能量。窗边花盆定期转向，能让植株长得更均衡。','植物向光','https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&w=900&q=82',true,'published'),
(71,(select id from public.interest_tags where name='知识'),'数字地图的比例尺','屏幕缩放改变的是显示范围，不是地面本身。比较两个地点距离时，需要留意地图比例尺和投影方式。','读懂比例尺','https://images.unsplash.com/photo-1544787219-7f47ccb76574?auto=format&fit=crop&w=900&q=82',true,'published'),
(72,(select id from public.interest_tags where name='知识'),'记忆为何需要间隔复习','拉开复习时间会促使大脑重新提取知识。每次尝试回忆，都能帮助发现真正还不熟悉的部分。','间隔记忆','https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&w=900&q=82',true,'published'),
(73,(select id from public.interest_tags where name='艺术'),'陶器上的釉色变化','釉料在高温中发生反应，窑内位置也会影响最终颜色。烧制的不确定性让同一配方留下细微差别。','窑火釉色','https://images.unsplash.com/photo-1449247709967-d4461a6a6103?auto=format&fit=crop&w=900&q=82',true,'published'),
(74,(select id from public.interest_tags where name='艺术'),'版画如何留下层次','不同颜色通常需要分版套印，纸张位置稍有偏差就会形成新的边缘。重复的手工步骤本身也是作品的一部分。','版画套色','https://images.unsplash.com/photo-1519608487953-e999c86e7455?auto=format&fit=crop&w=900&q=82',true,'published'),
(75,(select id from public.interest_tags where name='艺术'),'舞台灯光改变空间感','侧光会凸显身体动作，顶光则容易形成更强的戏剧气氛。灯光设计让观众感受到空间，而不只是看清演员。','舞台侧光','https://images.unsplash.com/photo-1567538096630-e0c55bd6374c?auto=format&fit=crop&w=900&q=82',true,'published'),
(76,(select id from public.interest_tags where name='艺术'),'从一段留白读诗','诗句之间的停顿也参与表达。把朗读速度放慢，留意换行处的呼吸，常能听见文字之外的节奏。','诗的停顿','https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=900&q=82',true,'published'),
(77,(select id from public.interest_tags where name='艺术'),'博物馆标签的文字分寸','标签需要交代作品背景，也要给观众留下观察空间。简洁准确的说明能帮助理解，却不替观众下结论。','展签文字','https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=900&q=82',true,'published'),
(78,(select id from public.interest_tags where name='艺术'),'街舞里的重心变化','动作的力量来自重心、节拍和停顿之间的关系。观察脚步如何接住身体，能看到技巧以外的表达。','身体节拍','https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?auto=format&fit=crop&w=900&q=82',true,'published'),
(79,(select id from public.interest_tags where name='情感'),'在帮助之前先问一句','有时朋友需要的只是有人听，而不是立刻得到解决方案。先问“你希望我听你说，还是一起想办法”，能让支持更贴近对方。','先听再帮','https://images.unsplash.com/photo-1544787219-7f47ccb76574?auto=format&fit=crop&w=900&q=82',true,'published'),
(80,(select id from public.interest_tags where name='知识'),'种子如何搭上风','蒲公英的绒毛增加空气阻力，让种子能随风移动更远。不同植物用不同结构把繁衍机会交给环境。','风中的种子','https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&w=900&q=82',true,'published')
